  /* ==========================================================================
     DICTIONARY (Terminology)
     ========================================================================== */
  "dictionary": {
    "Regolith": "Unconsolidated, toxic rocky dust and debris covering Martian solid bedrock. Contains 0.5%–1.0% toxic perchlorates requiring washing before agricultural use.",
    "ISRU (In-Situ Resource Utilization)": "Harnessing local extraterrestrial resources (e.g., harvesting Martian surface ice for water, CO2 for oxygen/fuel) rather than transporting supplies from Earth.",
    "Sabatier Chemical Synthesis": "A thermal chemical reaction (CO2 + 4H2 -> CH4 + 2H2O) used to produce liquid methane rocket propellant and water from Martian atmospheric CO2.",
    "Rodriguez Well (Rodwell)": "A subsurface mining technique where hot water (80°C) is recirculated down a narrow drill hole into subterranean ice sheets to melt and pump up liquid water pools.",
    "ECLSS": "Environmental Control and Life Support System — The closed-loop network responsible for air scrubbing, oxygen generation, water recovery, and pressure control.",
    "Tau (Optical Depth)": "A measure of atmospheric dust opacity. A Tau rating above 4.0 indicates a severe global dust storm that blocks over 99% of surface solar light.",
    "Perchlorates (ClO4-)": "Toxic chemical salts widespread in Martian soil that disrupt human thyroid and neurological function if ingested or inhaled.",
    "GPR (Ground-Penetrating Radar)": "Radar technology used by surface rovers to locate underground ice deposits, voids, and lava tube ceilings up to 15m deep.",
    "Basalt Sintering": "Using microwave heating (1,100°C) to melt raw regolith dust into solid interlocking bricks and radiation-protective outer shells."
  },
  
